<?php
// Out and About Books: sends the contact form and newsletter sign-ups to your inbox.
// This file is generated by build.mjs. Edit src/php/send.php, not the copy in _site.
// Needs PHP 7.4 or later with mail() enabled (standard on IONOS web hosting and most UK hosts).

const SEND_TO   = '__TO__';      // from "Contact email address" in Site settings
const SEND_FROM = '__FROM__';    // from "Website sender address" in Site settings
const SITE_NAME = '__SITE__';

const FORMS = [
  'contact'    => ['thanks' => '/contact/thanks/',    'back' => '/contact/'],
  'newsletter' => ['thanks' => '/newsletter/thanks/', 'back' => '/'],
  'review'     => ['thanks' => '/review/thanks/',     'back' => '/books/'],
];

header('X-Robots-Tag: noindex');
$wantsJson = stripos($_SERVER['HTTP_ACCEPT'] ?? '', 'application/json') !== false;

function finish(int $code, string $message, ?string $redirect = null): void {
  global $wantsJson;
  if ($wantsJson || !$redirect) {
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['ok' => $code < 400, 'message' => $message]);
  } else {
    header('Location: ' . $redirect, true, 303);
  }
  exit;
}

// Removes line breaks so nothing can be smuggled into the email headers.
function oneLine(string $s, int $max): string {
  return mb_substr(trim(preg_replace('/[\r\n\t]+/', ' ', $s)), 0, $max);
}

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') finish(405, 'Forms only.');

$form = $_POST['form-name'] ?? '';
if (!isset(FORMS[$form])) finish(400, 'Unknown form.');
$cfg = FORMS[$form];

// Spam traps: a hidden field real people never see. Bots fill it in; we pretend all is well.
if (trim($_POST['website'] ?? '') !== '' || trim($_POST['company'] ?? '') !== '') finish(200, 'Thanks.', $cfg['thanks']);

// Only accept posts from this website's own pages.
$origin = $_SERVER['HTTP_ORIGIN'] ?? ($_SERVER['HTTP_REFERER'] ?? '');
$host = $_SERVER['HTTP_HOST'] ?? '';
if ($origin !== '' && parse_url($origin, PHP_URL_HOST) !== preg_replace('/:\d+$/', '', $host)) finish(403, 'Not allowed.');

if (SEND_TO === '' || strpos(SEND_TO, '@') === false) finish(500, 'This form is not set up yet. Please email us instead.');

// Reviews send people back to the book they were reading about.
if ($form === 'review' && preg_match('#^/books/[a-z0-9-]+/$#', $_POST['back'] ?? '')) $cfg['back'] = $_POST['back'];

$email = oneLine($_POST['email'] ?? '', 254);
$emailOptional = $form === 'review';
if (!($emailOptional && $email === '') && !filter_var($email, FILTER_VALIDATE_EMAIL)) finish(422, 'Enter a valid email address.', $cfg['back']);

if ($form === 'contact') {
  $name    = oneLine($_POST['name'] ?? '', 120);
  $subject = oneLine($_POST['subject'] ?? '', 120);
  $message = mb_substr(trim(str_replace("\r\n", "\n", $_POST['message'] ?? '')), 0, 5000);
  if ($name === '' || $subject === '' || $message === '') finish(422, 'Fill in every field.', $cfg['back']);
  $mailSubject = SITE_NAME . ' website: ' . $subject;
  $body = "Name: $name\nEmail: $email\nSubject: $subject\n\n$message\n\n--\nSent from the contact form on your website. Reply to this email to answer $name.";
} elseif ($form === 'review') {
  $name    = oneLine($_POST['name'] ?? '', 80);
  $book    = oneLine($_POST['book'] ?? '', 200);
  $rating  = (int)($_POST['rating'] ?? 0);
  $review  = mb_substr(trim(str_replace("\r\n", "\n", $_POST['review'] ?? '')), 0, 3000);
  $consent = ($_POST['consent'] ?? '') === 'yes';
  if ($name === '' || $review === '' || $rating < 1 || $rating > 5) finish(422, 'Fill in your name, a star rating and your review.', $cfg['back']);
  if (!$consent) finish(422, 'Tick the box to let us publish your review.', $cfg['back']);
  $stars = str_repeat('★', $rating) . str_repeat('☆', 5 - $rating);
  $mailSubject = SITE_NAME . ": new review of $book ($rating/5)";
  $body = "A reader has sent a review. It isn't on the website yet.\n\nBook: $book\nRating: $stars ($rating out of 5)\nName to show: $name\nEmail (not published): " . ($email !== '' ? $email : 'not given') . "\n\nReview:\n$review\n\n--\nThey agreed that their name and review can be published.\nTo publish it, open the book in the editor or admin, go to Reader reviews, add a review and copy these details in word for word.";
} else {
  $mailSubject = SITE_NAME . ': new newsletter sign-up';
  $body = "$email has signed up to the newsletter on your website.\n\nAdd them to your mailing list. They agreed to receive the newsletter when they signed up.\n";
}

$headers = implode("\r\n", [
  'From: ' . SITE_NAME . ' website <' . SEND_FROM . '>',
  'Reply-To: ' . ($email !== '' ? $email : SEND_TO),
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: 8bit',
  'X-Mailer: OutAndAboutBooks',
]);
$encodedSubject = '=?UTF-8?B?' . base64_encode($mailSubject) . '?=';

if (!mail(SEND_TO, $encodedSubject, $body, $headers)) finish(502, 'Your message could not be sent. Please email us instead.');

finish(200, 'Sent.', $cfg['thanks']);
